    out.language=raw.language==='tw'?'tw':'cn'; out.tab=['waystone','tablet','equipment'].includes(raw.tab)?raw.tab:'waystone';
    for(const name of ['waystone','tablet','equipment']) {
      const src=raw[name]; if(!src || typeof src!=='object')continue;
      const p=out[name];
       for(const key of ['prefix','suffix','expanded','guideOnly'])if(typeof src[key]==='boolean')p[key]=src[key];
      if(typeof src.search==='string')p.search=src.search;
      p.match=['all','any','atleast2','atleast3','atleast4'].includes(src.match)?src.match:'all';
      p.types=Array.isArray(src.types)?[...new Set(src.types.filter(t=>D.types.some(x=>x[0]===t)))]:[];
      if(name==='equipment'){p.gearClass=E.classes.some(x=>x.id===src.gearClass)?src.gearClass:'all';p.gearTopic=E.topics.some(x=>x.id===src.gearTopic)?src.gearTopic:'all';const arches=E.archetypes?.[p.gearClass]||[];p.gearArchetype=arches.some(x=>x.id===src.gearArchetype)?src.gearArchetype:'all';}
      for(const [key,value] of Object.entries(src.values||{}))if(D.metrics.some(m=>m[0]===key)&&typeof value==='string'&&value.length<=32)p.values[key]=String(value);
      for(const key of ['tierMin','tierMax','usesMin','usesMax'])if(typeof src.basic?.[key]==='string'&&src.basic[key].length<=32)p.basic[key]=String(src.basic[key]);
      if(name==='waystone'&&/^[0-5]$/.test(String(src.basic?.revivals)))p.basic.revivals=String(src.basic.revivals);
      if(['normal','magic','rare'].includes(src.basic?.rarity))p.basic.rarity=src.basic.rarity;
      if(['yes','no'].includes(src.basic?.corruption))p.basic.corruption=src.basic.corruption;
      for(const a of allAffixes().filter(x=>x.page===name)) {
        const x=src.selected?.[a.id];
        if(x && ['include','exclude'].includes(x.mode))p.selected[a.id]={mode:x.mode,value:typeof x.value==='string'&&x.value.length<=32?x.value:'',value2:typeof x.value2==='string'&&x.value2.length<=32?x.value2:''};
      }
      if(name==='equipment'&&p.gearClass!=='all')for(const id of Object.keys(p.selected)){const a=E.affixes.find(x=>x.id===id);const allowed=a?.archetypesByClass?.[p.gearClass];if(!a?.classes.includes(p.gearClass)||(p.gearArchetype!=='all'&&allowed&&!allowed.includes(p.gearArchetype)))delete p.selected[id];}
    }
