    const recommendationTitle=stars?text('推荐星级：','推薦星級：')+ratingEntries.map(x=>labelOf(D.types.find(t=>t[0]===x.type))+' '+(x.stars?x.stars+text(' 星',' 星'):text('未标记','未標記'))).join(' / '):'';
    const starIcons=stars?Array.from({length:3},(_,i)=>`<span class="${i<stars?'lit':''}">★</span>`).join(''):'';
    const recommendationLabel=varied?text('最高 '+stars+' 星','最高 '+stars+' 星'):stars+text(' 星推荐',' 星推薦');
    const recommendationMark=stars?`<div class="recommendation-mark" title="${escape(recommendationTitle)}" aria-label="${escape(recommendationTitle)}"><span class="recommendation-stars" aria-hidden="true">${starIcons}</span><span class="recommendation-label">${recommendationLabel}</span></div>`:'';
    return `<article class="affix-row${selectedClass}${stars?' recommended':''}"><div class="affix-top"><div class="affix-info"><div class="affix-title">${nameOf(a)}</div>${note?`<div class="affix-note">${escape(note)}</div>`:''}<div class="affix-meta">${meta}</div></div>${recommendationMark}<div class="choice" role="group" aria-label="${nameOf(a)}"><button type="button" class="include" data-affix="${a.id}" data-mode="include" aria-pressed="${s?.mode==='include'}">${text('包含')}</button><button type="button" class="exclude" data-affix="${a.id}" data-mode="exclude" aria-pressed="${s?.mode==='exclude'}">${text('排除')}</button></div></div>${rollFilter(a,s)}${gearExtra(a,s)}</article>`;
